//! 🧪️ Real queue storage nulls and native payload closure preserve independent actual work under one finite bank.
use super::*;
use semio_framework_value_testing_allocator::{observe_retirement_allocations as observe,refuse_one_allocation_on_this_thread as refuse};
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn debit(bank:&mut RetainedCloneGrant,work:u64,p:RetainedCloneProgress){assert!(work<=bank.maximum_items as u64);assert!(p.fits(*bank));bank.maximum_items-=work as usize;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;}
#[test]
fn queue_actual_null_and_native_payload_close_use_one_original_bank(){
 let law:serde_json::Value=serde_json::from_str(include_str!("actual.json")).unwrap();let stock=&law["stock"];let mut bank=RetainedCloneGrant{maximum_items:stock["items"].as_u64().unwrap()as usize,maximum_copy_bytes:stock["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:stock["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:stock["release"].as_u64().unwrap()as usize,maximum_depth:stock["depth"].as_u64().unwrap()as usize};let mut queue=RetirementQueue::default();let d=queue.reserve_demand().unwrap();let g=grant(d);
 for denied in [RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g},RetainedCloneGrant{maximum_depth:0,..g}]{let(turn,heap)=observe(||queue.reserve_step(denied));assert_eq!(turn.work,law["deniedWork"].as_u64().unwrap());assert_eq!(heap,(0,0));assert!(queue.terminal_is_empty());assert_eq!(queue.reserve_demand().unwrap(),d);}
 let((turn,attempts),heap)=observe(||refuse(||queue.reserve_step(g)));assert_eq!(attempts,1);assert_eq!(turn.work,law["reserveNullWork"].as_u64().unwrap());assert_eq!(heap,(0,0));assert!(turn.result.is_err());debit(&mut bank,turn.work,queue.step_progress());assert!(queue.terminal_is_empty());
 let mut born=0;let mut freed=0;for _ in 0..law["maximumTurns"].as_u64().unwrap(){if queue.has_reserved_slot(){break}let g=grant(queue.reserve_demand().unwrap());let(turn,heap)=observe(||queue.reserve_step(g));let work=turn.work;let p=turn.result.unwrap();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));debit(&mut bank,work,p);born+=heap.0;freed+=heap.1;}assert!(queue.has_reserved_slot());
 let(value,heap)=observe(||law["text"].as_str().unwrap().to_owned());born+=heap.0;freed+=heap.1;assert_eq!(serde_json::to_value(&value).unwrap(),law["text"]);let g=RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:RetirementQueue::frame_birth_bytes::<String>(),maximum_depth:queue.len()+1,..Default::default()};let(turn,heap)=observe(||queue.admit_owned(value,g));let work=turn.work;let p=turn.result.map_err(|(error,_)|error).unwrap();assert_eq!(work,law["transferWork"].as_u64().unwrap());assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));debit(&mut bank,work,p);born+=heap.0;freed+=heap.1;
 for _ in 0..law["maximumTurns"].as_u64().unwrap(){if queue.terminal_is_empty(){break}let g=grant(queue.next_demand(1).unwrap());let(turn,heap)=observe(||semio_framework_value_retirement::advance_retirement_turn(queue.next_demand(1).unwrap(),g,|g|{let turn=queue.step(g);RetainedWorkOutcome{work:turn.work,result:turn.result.map(|step|(step,queue.terminal_is_empty()))}}));let work=turn.work;let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));debit(&mut bank,work,p);born+=heap.0;freed+=heap.1;}assert!(queue.terminal_is_empty());let(turn,heap)=observe(||queue.step(Default::default()));assert_eq!(turn.work,law["cachedWork"].as_u64().unwrap());assert_eq!(heap,(0,0));assert!(matches!(turn.result,Ok(RetainedCloneStep::Complete(p))if p==Default::default()));assert_eq!(observe(||drop(queue)).1,(0,0));assert_eq!(born,freed);
}
